import { breakpoints } from '../foundation/gridSystem';

// Shared between footer's split recipe files (footer.css.ts, footerNavColumn.css.ts,
// bottomBar.css.ts) so a breakpoint or provisional size can't drift between them the way a
// copy-pasted literal would. Not a general-purpose theme module — scope stays footer-only; see
// .claude/rules/overrideStyling.md's co-location guidance for why these no longer live in one
// flat theme/components/footer.ts.

// `tablet` mirrors the confirmed foundation token `breakpoints.md` — imported rather than
// retyped so the two cannot drift apart. `tabletWide` and `desktop` have no foundation
// equivalent yet; `desktop` additionally conflicts with Chakra's lg (62em) and xl (80em), which
// is why every desktop rule using this constant is a raw @media rather than a responsive prop.
// Media queries cannot consume var(), so this is the one deliberate exception to
// theme/components/ otherwise avoiding direct foundation/ imports in favour of --zimm-* CSS vars.
// audit-allow: raw em is correct and permanent here, not a placeholder awaiting a token —
// overrideStyling.md's Units section documents breakpoints as one of the few genuinely
// context-relative uses of em, deliberately outside the var(--zimm-*) scale system.
export const BP = {
  tablet: breakpoints.md, // Figma: alias/breakpoint/tablet — 768px
  tabletWide: '53.75em', // Figma: alias/breakpoint/tablet-wide — 860px (no foundation equivalent)
  desktop: '64em', // Figma: alias/breakpoint/desktop — 1024px (≠ Chakra lg=62em / xl=80em)
} as const;

// alias/size/footer/col-width-nav (140px). Provisional — kept as a named rem reference until
// the UI designer confirms it in foundation/sizes.ts. Used by both the nav column's own width
// (footerNavColumn.css.ts) and the bottom bar's mobile legal-link width (bottomBar.css.ts) — the
// two must match or the legal links stop lining up with the columns above them.
export const SIZE_COL_NAV = '8.75rem';

